int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    int ret = 0;
    struct hstate *h;
    unsigned long hmask;

    for (h = hstate; ret == 0 && addr < end; h = hstate_next(h)) {
        hmask = huge_page_mask(h);
        if (hmask < PAGE_SIZE)
            continue;

        if (addr & ~hmask) {
            addr = (addr & hmask) + hmask;
            if (addr < end)
                continue;
        }

        if (walk->vma && (addr < walk->vma->vm_start || addr >= walk->vma->vm_end)) {
            addr = ALIGN(addr, hmask);
            if (addr < end)
                continue;
        }

        if (walk->pte_entry) {
            ret = walk->pte_entry(addr, walk);
            if (ret < 0)
                break;
        }

        addr += hmask;
    }

    return ret;
}

int walk_huge_pages(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    int ret = 0;
    unsigned long next;
    struct hstate *h;
    unsigned long hmask;

    h = hstate_file(walk->vma->vm_file->f_mapping->host);
    hmask = huge_page_mask(h);

    while (addr < end) {
        next = (addr + 1) & hmask;
        if (next <= addr) {
            addr = (addr & hmask) + (1UL << h->order);
            continue;
        }

        if (walk->pmd_entry) {
            ret = walk->pmd_entry(addr, next, walk);
            if (ret)
                break;
        } else {
            ret = walk->pte_entry(addr, next, walk);
            if (ret)
                break;
        }

        addr = next;
    }

    return ret;
}

int walk_huge_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    while (addr < end) {
        unsigned long next = (addr + HPAGE_SIZE) & huge_page_mask(hstate);
        int ret;

        if (walk->vma && walk->vma->vm_start <= addr && walk->vma->vm_end >= addr) {
            ret = walk->fn(addr, next, walk);
            if (ret < 0)
                return ret;
        }

        addr = next;
    }

    return 0;
}

int walk_huge_memory_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    int ret = 0;

    while (addr < end) {
        struct hstate *h;
        unsigned long hmask;
        unsigned long start = addr;

        h = hstate_addr_to_hstate(start);
        if (!h)
            return -EINVAL;

        hmask = huge_page_mask(h);
        start = (start & ~(hmask));

        if (start < addr)
            start = addr;

        if (start >= end)
            break;

        ret = walk->pmd_entry(start, end, walk);
        if (ret)
            break;

        addr = ALIGN(addr, hmask);
    }

    return ret;
}

int walk_huge_pages(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    int ret = 0;

    while (addr < end) {
        unsigned long hpage_size = huge_page_size(hstate);
        unsigned long hpage_mask = huge_page_mask(hstate);
        struct vm_area_struct *vma = find_vma(current->mm, addr);

        if (!vma) {
            return -EFAULT;
        }

        if ((addr & hpage_mask) != 0) {
            addr = (addr & hpage_mask) + hpage_size;
            continue;
        }

        ret = walk->fn(addr, addr + hpage_size, vma, walk->private);
        if (ret < 0) {
            break;
        }

        addr += hpage_size;
    }

    return ret;
}
